const sha=(v:string)=>createHash('sha256').update(v).digest('hex');
const fail=(message:string,code='VALIDATION',status=400):never=>{throw new BusinessError(code,message,status)};
const check=(v:unknown,message:string,code='CONFLICT',status=409):void=>{if(!v)fail(message,code,status)};
const str=(v:unknown,name:string,max=4000)=>{check(typeof v==='string'&&!!v.trim()&&v.length<=max,`${name}无效`,'VALIDATION',400);return (v as string).trim()};
